    function run(uint256 a) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (a)); require(a <= 1000000000000000000000000000000);
        require(a > 0);
        require(a < type(uint256).max);
        c.deposit{value: a}(); if (__ESBMC_reverted()) return;
        bool revertedBig;
        c.withdraw(a + 1); bool __rev0 = __ESBMC_reverted(); if (__rev0) { revertedBig = true; } else { revertedBig = false; }
        bool revertedExact;
        c.withdraw(a); bool __rev1 = __ESBMC_reverted(); if (__rev1) { revertedExact = true; } else { revertedExact = false; }
        bool revertedAgain;
        c.withdraw(1); bool __rev2 = __ESBMC_reverted(); if (__rev2) { revertedAgain = true; } else { revertedAgain = false; }
