// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Wallet} from "../src/Wallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Wallet c;

    function setUp() public {
        c = new Wallet();
    }

    function _run(uint256 a) internal {
        a = bound(a, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(a > 0);
        vm.assume(a < type(uint256).max);
        try c.deposit{value: a}() {} catch { return; }
        bool revertedBig;
        try c.withdraw(a + 1) { revertedBig = false; } catch { revertedBig = true; }
        bool revertedExact;
        try c.withdraw(a) { revertedExact = false; } catch { revertedExact = true; }
        bool revertedAgain;
        try c.withdraw(1) { revertedAgain = false; } catch { revertedAgain = true; }
        assertTrue(revertedBig && !revertedExact && revertedAgain);
    }

    function testFuzz_run(uint256 a) public {
        _run(a);
    }

    receive() external payable {}
}
